-- ── hand-written: grants and row-level security ─────────────────────────────────────────────────
-- Read only. The owner, an accountant and the auditor read everyone's commission, on the
-- invoices they may read (a member limited to some branches: those branches' invoices). Anyone
-- reads their own, and a manager also reads that of everyone below them in the sales
-- hierarchy, at any depth (the founder's decision, 2026-11-15): "manager" is whoever has
-- people under them there, whatever their role.

-- The signed-in member and everyone below them in the sales hierarchy, as it stands now. For
-- the policies below, which ask it once for each statement.
CREATE FUNCTION app.commission_team() RETURNS uuid[]
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    WITH RECURSIVE below (user_id, depth) AS (
      SELECT app.current_user_id(), 0
      UNION ALL
      SELECT h.user_id, below.depth + 1 FROM below
      JOIN public.sales_hierarchy h ON h.tenant_id = app.tenant_id() AND h.manager_user_id = below.user_id
      WHERE below.depth < 50
    )
    SELECT coalesce(array_agg(DISTINCT below.user_id), '{}') FROM below WHERE below.user_id IS NOT NULL AND app.tenant_role() IS NOT NULL
  $$;
--> statement-breakpoint
