-- ── hand-written: movements are never changed, and an accrual is their sum ──────────────────────
-- A movement is written once. It leaves only with its whole company, when the tests remove a
-- synthetic one (as for stock moves, drizzle/0017_delivery_notes.sql).
CREATE FUNCTION app.refuse_commission_change() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND session_user = 'postgres'
     AND OLD.tenant_id::text = ANY (string_to_array(coalesce(current_setting('app.purge_tenants', true), ''), ','))
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'a commission movement is never changed or removed' USING ERRCODE = 'SE315';
END $$;
