-- Asked when the transaction ends, for every accrual written or changed in it: what it says
-- was first accrued, is still earned, has been released and has been paid is exactly what its
-- movements add up to. And what it was first worked out as, on what, for whom, never changes.
CREATE FUNCTION app.check_commission_accrual() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_row public.commission_accruals%ROWTYPE;
  v_accrued numeric;
  v_earned numeric;
  v_released numeric;
  v_paid numeric;
BEGIN
  IF TG_OP = 'UPDATE' AND (to_jsonb(NEW) - ARRAY['earned', 'released', 'paid', 'approved_at', 'approved_by']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['earned', 'released', 'paid', 'approved_at', 'approved_by']) THEN
    RAISE EXCEPTION 'what a commission was worked out as never changes' USING ERRCODE = 'SE316';
  END IF;
  SELECT a.* INTO v_row FROM public.commission_accruals a WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT coalesce(sum(m.amount) FILTER (WHERE m.type = 'accrued'), 0),
         coalesce(sum(m.amount) FILTER (WHERE m.type IN ('accrued', 'entitlement_adjusted')), 0),
         coalesce(sum(CASE m.type WHEN 'released' THEN m.amount WHEN 'release_reversed' THEN -m.amount END), 0),
         coalesce(sum(CASE m.type WHEN 'paid' THEN m.amount WHEN 'recovery_recorded' THEN -m.amount END), 0)
    INTO v_accrued, v_earned, v_released, v_paid
    FROM public.commission_movements m WHERE m.tenant_id = v_row.tenant_id AND m.accrual_id = v_row.id;
  IF v_row.accrued <> v_accrued OR v_row.earned <> v_earned OR v_row.released <> v_released OR v_row.paid <> v_paid THEN
    RAISE EXCEPTION 'a commission is the sum of its movements' USING ERRCODE = 'SE316';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_commission_accrual() FROM PUBLIC;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER commission_accruals_sum
  AFTER INSERT OR UPDATE ON public.commission_accruals
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.check_commission_accrual();
--> statement-breakpoint
ALTER TABLE public.commission_accruals ENABLE ALWAYS TRIGGER commission_accruals_sum;
--> statement-breakpoint
CREATE TRIGGER commission_accruals_kept
  BEFORE DELETE ON public.commission_accruals
