-- ── hand-written: the lists the whole app shares ────────────────────────────────────────────────
-- Each added with a function of this step's own, as drizzle/0019_journal_documents.sql says.

-- A journal carries a document's number only when it is that document's own (a number names
-- one journal in a company), so the two journals below carry none: they are found by their
-- source, the invoice or the credit note.
--
-- The journal of what an invoice's sales team earned stands with the posted invoice it names.
CREATE FUNCTION app.journal_backed_commission_accrual(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = p_journal.tenant_id AND d.id = p_journal.source_id AND d.kind = 'invoice' AND d.status = 'submitted'
        AND p_journal.document_number IS NULL AND d.document_date = p_journal.journal_date
        AND EXISTS (SELECT 1 FROM public.commission_accruals a WHERE a.tenant_id = d.tenant_id AND a.invoice_id = d.id))
  $$;
--> statement-breakpoint
-- The journal that takes commission back when goods are returned stands with the posted credit
-- note it names, whose invoice had commission on it.
CREATE FUNCTION app.journal_backed_commission_return(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.sales_documents n
      WHERE n.tenant_id = p_journal.tenant_id AND n.id = p_journal.source_id AND n.kind = 'credit_note' AND n.status = 'submitted'
        AND p_journal.document_number IS NULL AND n.document_date = p_journal.journal_date
        AND EXISTS (SELECT 1 FROM public.commission_movements m WHERE m.tenant_id = n.tenant_id AND m.source_type = 'credit_note' AND m.source_id = n.id AND m.type = 'entitlement_adjusted'))
  $$;
--> statement-breakpoint
CREATE FUNCTION app.journal_backed_commission_payment(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.commission_payments p
      WHERE p.tenant_id = p_journal.tenant_id AND p.id = p_journal.source_id AND p.journal_id = p_journal.id
        AND p.number = p_journal.document_number AND p.payment_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
