-- ── hand-written: the parts the functions below share ───────────────────────────────────────────
-- None of these is for the app to call.

-- What a salesperson has sold in a calendar month, for the slabs and the target of their plan:
-- their shares of the lines of invoices dated in the month, less their shares of what came back
-- on credit notes dated in the month. Never below nothing.
CREATE FUNCTION app.commission_month_sales(p_tenant uuid, p_user uuid, p_date date) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT greatest(coalesce(sum(m.base), 0), 0)
    FROM public.commission_movements m
    JOIN public.commission_accruals a ON a.tenant_id = m.tenant_id AND a.id = m.accrual_id
    WHERE m.tenant_id = p_tenant AND a.user_id = p_user AND a.kind = 'own'
      -- Worked out without a time zone: the month is the calendar's, whatever the session is set to.
      AND m.movement_date >= date_trunc('month', p_date::timestamp)::date AND m.movement_date < (date_trunc('month', p_date::timestamp) + interval '1 month')::date
  $$;
--> statement-breakpoint
-- The money that has come in for an invoice, for commission: what receipts that count have
-- paid of it. Cash and bank money count once the receipt is posted, a cheque once it has cleared.
CREATE FUNCTION app.commission_money_in(p_tenant uuid, p_invoice uuid) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT coalesce(sum(a.amount), 0) FROM public.receipt_allocations a
    JOIN public.receipts r ON r.tenant_id = a.tenant_id AND r.id = a.receipt_id
    WHERE a.tenant_id = p_tenant AND a.invoice_id = p_invoice AND a.posted_at IS NOT NULL AND a.voided_at IS NULL
      AND r.status = 'posted' AND (r.method IN ('cash', 'bank') OR r.cheque_status = 'cleared')
  $$;
--> statement-breakpoint
-- How much of an invoice has been collected, for commission: the money that has come in for
-- it, and credit from ANOTHER invoice's credit note set against it. That credit is money that
-- came in earlier, for goods that have since come back; it counts only while the invoice it
-- came from is itself settled by money and credit. (If that invoice's cheque bounces, or has
-- not cleared yet, the credit is not money in hand, and stops counting until it is.)
CREATE FUNCTION app.commission_collected(p_tenant uuid, p_invoice uuid) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT app.commission_money_in(p_tenant, p_invoice)
      + coalesce((
        SELECT sum(c.amount) FROM public.credit_note_allocations c
        JOIN public.sales_documents n ON n.tenant_id = c.tenant_id AND n.id = c.credit_note_id
        JOIN public.sales_documents o ON o.tenant_id = n.tenant_id AND o.id = n.source_document_id
        WHERE c.tenant_id = p_tenant AND c.invoice_id = p_invoice AND n.source_document_id <> p_invoice
          AND app.commission_money_in(p_tenant, o.id)
              + coalesce((SELECT sum(x.amount) FROM public.credit_note_allocations x WHERE x.tenant_id = p_tenant AND x.invoice_id = o.id), 0) >= o.total), 0)
  $$;
--> statement-breakpoint
-- Brings every accrual of one invoice up to date with what has happened to the invoice, and
-- writes a movement for each change. It can be asked any number of times: it works out where
-- each accrual should stand and moves it there.
--
--   earned    what was accrued, in the proportion of the line's goods that have not come back
--             (goods on posted credit notes of the invoice);
--   released  what is earned, in the proportion of the invoice that has been collected: what
--             is left of it to collect is its total less its credit notes. An invoice with
--             nothing to collect (one that came to nothing) has nothing to wait for.
--
-- p_source and p_source_id say what happened (a receipt, a credit note), p_date when. A fall
-- in what is earned is posted: debit Commission payable, credit Sales commission, one journal
-- for each credit note. Any change clears an approval: what was approved is no longer the figure.
--
-- Everything that changes what a customer owes takes the customer's lock first (as receipts,
-- credit notes and invoices do), and only then is anything read: two things happening to one
-- invoice at the same moment (a cheque clearing while a receipt is cancelled) take their turn,
-- and the second sees what the first did. Credit that went from this invoice to another one
-- counts there only while this invoice is settled, so those invoices are brought up to date too.
CREATE FUNCTION app.refresh_commission(p_tenant uuid, p_invoice uuid, p_source text, p_source_id uuid, p_date date, p_depth integer DEFAULT 0) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_user uuid := app.current_user_id();
  v_invoice public.sales_documents%ROWTYPE;
  v_note public.sales_documents%ROWTYPE;
  v_remaining numeric;
  v_ratio numeric;
  v_row record;
  v_other uuid;
  v_earned numeric;
  v_released numeric;
  v_base numeric;
  v_taken numeric := 0;
  v_journal uuid;
BEGIN
  SELECT d.* INTO v_invoice FROM public.sales_documents d WHERE d.tenant_id = p_tenant AND d.id = p_invoice AND d.kind = 'invoice';
  IF NOT FOUND THEN
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || p_tenant::text || ':' || v_invoice.customer_id::text, 0));
  -- An accrual and its movements are written in whatever order suits; that they agree is asked when the transaction ends.
  SET CONSTRAINTS public.commission_accruals_sum DEFERRED;

  -- Read only now, after the lock: what is collected and what is left to collect as they stand.
  v_remaining := v_invoice.total - coalesce((
    SELECT sum(n.total) FROM public.sales_documents n
    WHERE n.tenant_id = p_tenant AND n.source_document_id = p_invoice AND n.kind = 'credit_note' AND n.status = 'submitted'), 0);
  v_ratio := CASE WHEN v_remaining > 0 THEN least(1, app.commission_collected(p_tenant, p_invoice) / v_remaining) ELSE 1 END;

  FOR v_row IN
    SELECT a.id, a.accrued, a.earned, a.released, a.base, a.kind, l.quantity AS invoiced,
           coalesce((
             SELECT sum(r.quantity) FROM public.sales_lines r
             JOIN public.sales_documents n ON n.tenant_id = r.tenant_id AND n.id = r.document_id
             WHERE r.tenant_id = p_tenant AND r.source_line_id = l.id AND n.kind = 'credit_note' AND n.status = 'submitted'), 0) AS returned,
           coalesce((SELECT sum(m.base) FROM public.commission_movements m WHERE m.tenant_id = p_tenant AND m.accrual_id = a.id), 0) AS base_left
    FROM public.commission_accruals a
    JOIN public.sales_lines l ON l.tenant_id = a.tenant_id AND l.id = a.line_id
    WHERE a.tenant_id = p_tenant AND a.invoice_id = p_invoice
    ORDER BY a.id
    FOR UPDATE OF a
  LOOP
    -- Goods only ever come back: what is earned, and the sale's part in the month, only ever fall.
    v_earned := least(v_row.earned, CASE WHEN v_row.returned >= v_row.invoiced THEN 0 ELSE round(v_row.accrued * (v_row.invoiced - v_row.returned) / v_row.invoiced, 4) END);
    v_released := round(v_earned * v_ratio, 4);
    -- The seller's sales for the month the return is dated in fall by the share that came back,
    -- whether or not the sale had earned anything (a first slab at nothing still fills the month).
    v_base := CASE WHEN v_row.kind <> 'own' THEN 0
                   WHEN v_row.returned >= v_row.invoiced THEN -v_row.base_left
                   ELSE least(round(v_row.base * (v_row.invoiced - v_row.returned) / v_row.invoiced, 4) - v_row.base_left, 0) END;
    IF v_earned < v_row.earned OR v_base < 0 THEN
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, base, movement_date, source_type, source_id, created_by)
        VALUES (p_tenant, v_row.id, 'entitlement_adjusted', v_earned - v_row.earned, v_base, p_date, p_source, p_source_id, v_user);
      v_taken := v_taken + (v_row.earned - v_earned);
      IF p_source <> 'credit_note' THEN
        RAISE EXCEPTION 'what is earned in commission falls only when goods come back' USING ERRCODE = 'SE316';
      END IF;
    END IF;
    IF v_released > v_row.released THEN
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
        VALUES (p_tenant, v_row.id, 'released', v_released - v_row.released, p_date, p_source, p_source_id, v_user);
    ELSIF v_released < v_row.released THEN
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
        VALUES (p_tenant, v_row.id, 'release_reversed', v_row.released - v_released, p_date, p_source, p_source_id, v_user);
    END IF;
    IF v_earned <> v_row.earned OR v_released <> v_row.released THEN
      UPDATE public.commission_accruals a SET earned = v_earned, released = v_released, approved_at = NULL, approved_by = NULL
        WHERE a.tenant_id = p_tenant AND a.id = v_row.id;
    END IF;
  END LOOP;

  IF v_taken > 0 THEN
    SELECT n.* INTO v_note FROM public.sales_documents n WHERE n.tenant_id = p_tenant AND n.id = p_source_id AND n.kind = 'credit_note';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'what is earned in commission falls only when goods come back' USING ERRCODE = 'SE316';
    END IF;
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (p_tenant, v_note.document_date, 'commission_return', v_note.id, NULL, left('Commission taken back: ' || v_note.number || ', goods returned on ' || v_invoice.number, 500), v_note.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (p_tenant, v_journal, 1, app.control_account(p_tenant, 'commission_payable'), v_taken, 0, 'Commission no longer owed'),
             (p_tenant, v_journal, 2, app.control_account(p_tenant, 'commission_expense'), 0, v_taken, 'Commission on goods returned');
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (p_tenant, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', v_note.document_date, 'source', 'commission_return', 'sourceId', v_note.id, 'number', NULL, 'lines', 2, 'total', v_taken::text));
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (p_tenant, v_user, app.tenant_role(), 'commission.return', 'sales_document', v_note.id,
        jsonb_build_object('creditNote', v_note.number, 'invoice', v_invoice.number, 'takenBack', v_taken::text));
  END IF;

  -- The invoices this one's credit went to: what they have collected may have changed with it.
  -- (Not for ever round a circle of credit: a few steps, each of which can be asked again.)
  IF p_depth < 5 THEN
    FOR v_other IN
      SELECT DISTINCT c.invoice_id FROM public.credit_note_allocations c
      JOIN public.sales_documents n ON n.tenant_id = c.tenant_id AND n.id = c.credit_note_id
      WHERE c.tenant_id = p_tenant AND n.source_document_id = p_invoice AND c.invoice_id IS NOT NULL AND c.invoice_id <> p_invoice
      ORDER BY c.invoice_id
    LOOP
      PERFORM app.refresh_commission(p_tenant, v_other, p_source, p_source_id, p_date, p_depth + 1);
    END LOOP;
  END IF;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_month_sales(uuid, uuid, date), app.commission_money_in(uuid, uuid), app.commission_collected(uuid, uuid), app.refresh_commission(uuid, uuid, text, uuid, date, integer) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_month_sales(uuid, uuid, date), app.commission_money_in(uuid, uuid), app.commission_collected(uuid, uuid), app.refresh_commission(uuid, uuid, text, uuid, date, integer)
  FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: an invoice is posted, a credit note is posted ─────────────────────────────────
-- Fired when a sales invoice or a credit note goes from draft to posted, which only their own
-- posting functions can do (drizzle/0018_sales_invoices.sql, the credit notes migration).
--
-- An invoice: every salesperson with a share of a line (the shares are the order's, written by
-- app.post_sales_invoice before it marks the invoice posted) earns what their plan gives on
-- that share, and each manager above them their plan's team rate on it. The seller's sales so
-- far this month, which slabs and a target are measured on, are read under a lock on the
-- seller's membership, which the app's role cannot take: two invoices of one salesperson
-- posted at once take their turn. A line's commission is worked out here once and never again.
--
-- A credit note: its invoice's accruals are brought up to date (app.refresh_commission).
CREATE FUNCTION app.commission_after_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_user uuid := app.current_user_id();
  v_row record;
  v_manager record;
  v_base numeric;
  v_quantity numeric;
  v_before numeric;
  v_plan uuid;
  v_amount numeric;
  v_accrual uuid;
  v_total numeric := 0;
  v_count integer := 0;
  v_journal uuid;
BEGIN
  IF NEW.kind = 'credit_note' THEN
    PERFORM app.refresh_commission(NEW.tenant_id, NEW.source_document_id, 'credit_note', NEW.id, NEW.document_date);
    RETURN NULL;
  END IF;
  -- An accrual and its movements are written in whatever order suits; that they agree is asked when the transaction ends.
  SET CONSTRAINTS public.commission_accruals_sum DEFERRED;

  -- Each seller's membership, in the same order for every invoice.
  PERFORM 1 FROM public.memberships m
    WHERE m.tenant_id = NEW.tenant_id AND m.user_id IN (
      SELECT s.user_id FROM public.sales_line_salespeople s WHERE s.tenant_id = NEW.tenant_id AND s.document_id = NEW.id)
    ORDER BY m.user_id
    FOR NO KEY UPDATE;

  FOR v_row IN
    SELECT l.id AS line_id, l.item_id, l.value, l.base_quantity, s.user_id, s.share_percent
    FROM public.sales_lines l
    JOIN public.sales_line_salespeople s ON s.tenant_id = l.tenant_id AND s.document_id = l.document_id AND s.line_id = l.id
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id
    ORDER BY l.line_no, s.user_id
  LOOP
    v_base := round(v_row.value * NEW.exchange_rate * v_row.share_percent / 100, 4);
    v_quantity := round(v_row.base_quantity * v_row.share_percent / 100, 4);
    v_before := app.commission_month_sales(NEW.tenant_id, v_row.user_id, NEW.document_date);
    v_plan := NULL;
    SELECT c.plan_id, c.amount INTO v_plan, v_amount
      FROM app.commission_on_line(NEW.tenant_id, v_row.user_id, NEW.document_date, v_row.item_id, NEW.customer_id, v_base, v_quantity, v_before) c;
    IF FOUND THEN
      INSERT INTO public.commission_accruals (tenant_id, invoice_id, line_id, invoice_date, user_id, kind, level, seller_user_id, plan_id, share_percent, base, quantity, accrued, earned, created_by)
        VALUES (NEW.tenant_id, NEW.id, v_row.line_id, NEW.document_date, v_row.user_id, 'own', 0, v_row.user_id, v_plan, v_row.share_percent, v_base, v_quantity, v_amount, v_amount, v_user)
        RETURNING id INTO v_accrual;
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, base, movement_date, source_type, source_id, created_by)
        VALUES (NEW.tenant_id, v_accrual, 'accrued', v_amount, v_base, NEW.document_date, 'sales_invoice', NEW.id, v_user);
      v_total := v_total + v_amount;
      v_count := v_count + 1;
    END IF;
    -- Everyone above the seller, on the seller's share, at the team rate of their own plan.
    FOR v_manager IN
      SELECT g.level, g.manager_user_id, g.plan_id, g.team_rate FROM app.commission_managers(NEW.tenant_id, v_row.user_id, NEW.document_date) g
      WHERE g.team_rate > 0
    LOOP
      v_amount := round(v_base * v_manager.team_rate / 100, 4);
      INSERT INTO public.commission_accruals (tenant_id, invoice_id, line_id, invoice_date, user_id, kind, level, seller_user_id, plan_id, share_percent, base, quantity, team_rate, accrued, earned, created_by)
        VALUES (NEW.tenant_id, NEW.id, v_row.line_id, NEW.document_date, v_manager.manager_user_id, 'team', v_manager.level, v_row.user_id, v_manager.plan_id, v_row.share_percent, v_base, v_quantity, v_manager.team_rate, v_amount, v_amount, v_user)
        RETURNING id INTO v_accrual;
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
        VALUES (NEW.tenant_id, v_accrual, 'accrued', v_amount, NEW.document_date, 'sales_invoice', NEW.id, v_user);
      v_total := v_total + v_amount;
      v_count := v_count + 1;
    END LOOP;
  END LOOP;

  -- Commission that comes to nothing leaves no journal.
  IF v_total > 0 THEN
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (NEW.tenant_id, NEW.document_date, 'commission_accrual', NEW.id, NULL, left('Commission earned on ' || NEW.number, 500), NEW.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (NEW.tenant_id, v_journal, 1, app.control_account(NEW.tenant_id, 'commission_expense'), v_total, 0, 'Commission earned by the sales team'),
             (NEW.tenant_id, v_journal, 2, app.control_account(NEW.tenant_id, 'commission_payable'), 0, v_total, 'Commission owed to the sales team');
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (NEW.tenant_id, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', NEW.document_date, 'source', 'commission_accrual', 'sourceId', NEW.id, 'number', NULL, 'lines', 2, 'total', v_total::text));
  END IF;
  IF v_count > 0 THEN
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (NEW.tenant_id, v_user, app.tenant_role(), 'commission.accrue', 'sales_document', NEW.id,
        jsonb_build_object('invoice', NEW.number, 'accruals', v_count, 'earned', v_total::text));
    -- An invoice that comes to nothing has nothing to collect: what it earned (so much a unit) is released at once.
    PERFORM app.refresh_commission(NEW.tenant_id, NEW.id, 'sales_invoice', NEW.id, NEW.document_date);
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_after_document() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER sales_documents_commission
  AFTER UPDATE ON public.sales_documents
  FOR EACH ROW
  WHEN (OLD.status = 'draft' AND NEW.status = 'submitted' AND NEW.kind IN ('invoice', 'credit_note'))
  EXECUTE FUNCTION app.commission_after_document();
--> statement-breakpoint
ALTER TABLE public.sales_documents ENABLE ALWAYS TRIGGER sales_documents_commission;
