-- ── hand-written: money comes in, or goes back ──────────────────────────────────────────────────
-- What a receipt pays of an invoice starts to count (the receipt is posted, or part of an
-- advance is set against the invoice) or stops counting (the receipt bounced or was
-- cancelled): the invoice's commission is brought up to date. For a cheque nothing is released
-- until it clears; the trigger on receipts below sees to that.
CREATE FUNCTION app.commission_after_allocation() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_date date := NEW.allocated_on;
BEGIN
  -- A row that stops counting does so on the day its receipt was taken back: the day of the
  -- journal that reversed the receipt's own, which is posted before the rows are stopped.
  IF NEW.voided_at IS NOT NULL THEN
    SELECT j.journal_date INTO v_date FROM public.receipts r
      JOIN public.journals j ON j.tenant_id = r.tenant_id AND j.reverses_journal_id = r.journal_id
      WHERE r.tenant_id = NEW.tenant_id AND r.id = NEW.receipt_id;
  END IF;
  PERFORM app.refresh_commission(NEW.tenant_id, NEW.invoice_id, 'receipt', NEW.receipt_id, coalesce(v_date, (now() AT TIME ZONE 'Asia/Karachi')::date));
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_after_allocation() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER receipt_allocations_commission_counted
  AFTER INSERT ON public.receipt_allocations
  FOR EACH ROW
  WHEN (NEW.invoice_id IS NOT NULL AND NEW.posted_at IS NOT NULL)
  EXECUTE FUNCTION app.commission_after_allocation();
--> statement-breakpoint
ALTER TABLE public.receipt_allocations ENABLE ALWAYS TRIGGER receipt_allocations_commission_counted;
--> statement-breakpoint
CREATE TRIGGER receipt_allocations_commission_changed
  AFTER UPDATE ON public.receipt_allocations
  FOR EACH ROW
  WHEN (NEW.invoice_id IS NOT NULL AND (NEW.posted_at IS DISTINCT FROM OLD.posted_at OR NEW.voided_at IS DISTINCT FROM OLD.voided_at))
  EXECUTE FUNCTION app.commission_after_allocation();
--> statement-breakpoint
ALTER TABLE public.receipt_allocations ENABLE ALWAYS TRIGGER receipt_allocations_commission_changed;
--> statement-breakpoint
-- A receipt is posted, a cheque clears, a receipt bounces or is cancelled: every invoice it
-- pays is brought up to date, dated the day it happened.
CREATE FUNCTION app.commission_after_receipt() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_invoice uuid;
  v_date date := coalesce(
    CASE WHEN NEW.status = 'bounced' THEN NEW.bounced_on WHEN NEW.cheque_status = 'cleared' THEN NEW.cleared_on END,
    CASE WHEN NEW.status = 'posted' AND OLD.status = 'draft' THEN NEW.receipt_date END,
    (SELECT j.journal_date FROM public.journals j WHERE j.tenant_id = NEW.tenant_id AND j.reverses_journal_id = NEW.journal_id),
    (now() AT TIME ZONE 'Asia/Karachi')::date);
BEGIN
  FOR v_invoice IN
    SELECT DISTINCT a.invoice_id FROM public.receipt_allocations a
    WHERE a.tenant_id = NEW.tenant_id AND a.receipt_id = NEW.id AND a.invoice_id IS NOT NULL AND a.posted_at IS NOT NULL
    ORDER BY a.invoice_id
  LOOP
    PERFORM app.refresh_commission(NEW.tenant_id, v_invoice, 'receipt', NEW.id, v_date);
  END LOOP;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_after_receipt() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER receipts_commission
  AFTER UPDATE ON public.receipts
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status OR NEW.cheque_status IS DISTINCT FROM OLD.cheque_status)
  EXECUTE FUNCTION app.commission_after_receipt();
--> statement-breakpoint
ALTER TABLE public.receipts ENABLE ALWAYS TRIGGER receipts_commission;
