-- A credit note's credit is set against an invoice: for another invoice than its own that is
-- money collected (it came in earlier, for the goods that have since come back).
CREATE FUNCTION app.commission_after_credit() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  PERFORM app.refresh_commission(NEW.tenant_id, NEW.invoice_id, 'credit_note', NEW.credit_note_id, NEW.allocated_on);
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_after_credit() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER credit_note_allocations_commission
  AFTER INSERT ON public.credit_note_allocations
  FOR EACH ROW
  WHEN (NEW.invoice_id IS NOT NULL)
  EXECUTE FUNCTION app.commission_after_credit();
