-- ── hand-written: approval ──────────────────────────────────────────────────────────────────────
-- The owner or an accountant approves what has been released and not yet paid of the accruals
-- named. Each must have something released and unpaid (SE311). The approval is for the figure
-- as it stands: any later change to the accrual clears it. Returns how many were approved.
CREATE FUNCTION app.approve_commission(p_accruals uuid[]) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_ids uuid[];
  v_count integer;
  v_total numeric;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot approve commission' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'commission is approved and paid in read committed transactions' USING ERRCODE = 'SE312';
  END IF;
  SELECT array_agg(DISTINCT x.id) INTO v_ids FROM unnest(p_accruals) AS x(id) WHERE x.id IS NOT NULL;
  IF v_ids IS NULL OR cardinality(v_ids) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'name between 1 and 1000 commissions' USING ERRCODE = 'check_violation';
  END IF;
  -- Held, but never waited for: a receipt, a return or a cheque being recorded on one of these
  -- invoices at this moment has them, and is about to change the figure. Approval steps aside
  -- (SE318) and is asked again, so that it can never stand in the way of a posting.
  BEGIN
    PERFORM 1 FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids) ORDER BY a.id FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'something is being recorded on one of these invoices right now; try again' USING ERRCODE = 'SE318';
  END;
  -- One that is not there, or is on another branch's invoice, is refused in the same words.
  IF (SELECT count(*) FROM public.commission_accruals a
      JOIN public.sales_documents d ON d.tenant_id = a.tenant_id AND d.id = a.invoice_id
      WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids) AND (v_scope IS NULL OR d.branch_id = ANY (v_scope))) <> cardinality(v_ids) THEN
    RAISE EXCEPTION 'no such commission in this company' USING ERRCODE = 'SE310';
  END IF;
  IF EXISTS (SELECT 1 FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids) AND a.released <= a.paid) THEN
    RAISE EXCEPTION 'There is no released unpaid commission to approve.' USING ERRCODE = 'SE311';
  END IF;
  UPDATE public.commission_accruals a SET approved_at = now(), approved_by = v_user
    WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids);
  SELECT count(*), sum(a.released - a.paid) INTO v_count, v_total FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, after)
    VALUES (v_tenant, v_user, v_role, 'commission.approve', 'commission',
      jsonb_build_object('commissions', v_count, 'approved', v_total::text, 'what', (
        SELECT jsonb_agg(jsonb_build_object('accrual', a.id, 'person', a.user_id, 'invoice', a.invoice_id, 'amount', (a.released - a.paid)::text) ORDER BY a.id)
        FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.id = ANY (v_ids))));
  RETURN v_count;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.approve_commission(uuid[]) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.approve_commission(uuid[]) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: payment ───────────────────────────────────────────────────────────────────────
-- Pays one person everything of theirs that is approved, on a day, from a cash or bank account,
-- by the owner or an accountant who works across the whole company (a person's commission
-- comes from every branch). What the person owes back comes off first: commission paid on a
-- sale that was undone afterwards (paid more than is now released), oldest first, as far as
-- this payment goes; the rest is carried to the next. The money that leaves is the difference:
--
--   debit   Commission payable
--   credit  the cash or bank account
--
-- Refused: nothing approved to pay (SE311), a date that has not come (SE313), an account that
-- is not a cash or bank account in use (SE314), a closed period.
CREATE FUNCTION app.pay_commission(p_user uuid, p_date date, p_account uuid, p_note text DEFAULT NULL)
  RETURNS TABLE (id uuid, number text, gross numeric, recovered numeric, amount numeric)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_me uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_row record;
  v_id uuid := gen_random_uuid();
  v_gross numeric := 0;
  v_owed numeric;
  v_recovered numeric := 0;
  v_take numeric;
  v_amount numeric;
  v_number text;
  v_journal uuid;
  v_name text;
BEGIN
  IF v_tenant IS NULL OR v_me IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot pay commission' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'commission is paid by someone who works across the whole company' USING ERRCODE = 'SE317';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'commission is approved and paid in read committed transactions' USING ERRCODE = 'SE312';
  END IF;
  IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE313';
  END IF;
  -- The person's membership is held: nothing is accrued for them, and no second payment made, meanwhile.
  SELECT m.email INTO v_name FROM public.memberships m WHERE m.tenant_id = v_tenant AND m.user_id = p_user FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such commission in this company' USING ERRCODE = 'SE310';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts a
    WHERE a.tenant_id = v_tenant AND a.id = p_account AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'commission is paid from a cash or a bank account that is in use' USING ERRCODE = 'SE314';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  -- As for approval: never waited for (SE318).
  BEGIN
    PERFORM 1 FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.user_id = p_user ORDER BY a.id FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'something is being recorded on one of this person''s invoices right now; try again' USING ERRCODE = 'SE318';
  END;
  -- Not before the commission it pays was released.
  IF EXISTS (
    SELECT 1 FROM public.commission_accruals a
    JOIN public.commission_movements m ON m.tenant_id = a.tenant_id AND m.accrual_id = a.id
    WHERE a.tenant_id = v_tenant AND a.user_id = p_user AND a.approved_at IS NOT NULL AND a.released > a.paid AND m.movement_date > p_date
  ) THEN
    RAISE EXCEPTION 'commission is paid on or after the day it was released' USING ERRCODE = 'SE319';
  END IF;

  -- What is approved, released and unpaid.
  FOR v_row IN
    SELECT a.id, a.released - a.paid AS due FROM public.commission_accruals a
    WHERE a.tenant_id = v_tenant AND a.user_id = p_user AND a.approved_at IS NOT NULL AND a.released > a.paid
    ORDER BY a.invoice_date, a.id
  LOOP
    INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
      VALUES (v_tenant, v_row.id, 'paid', v_row.due, p_date, 'commission_payment', v_id, v_me);
    UPDATE public.commission_accruals a SET paid = a.paid + v_row.due, approved_at = NULL, approved_by = NULL WHERE a.tenant_id = v_tenant AND a.id = v_row.id;
    v_gross := v_gross + v_row.due;
  END LOOP;
  IF v_gross <= 0 THEN
    RAISE EXCEPTION 'There is no approved commission to pay.' USING ERRCODE = 'SE311';
  END IF;

  -- What the person owes back, oldest first, as far as this payment goes.
  FOR v_row IN
    SELECT a.id, a.paid - a.released AS owed FROM public.commission_accruals a
    WHERE a.tenant_id = v_tenant AND a.user_id = p_user AND a.paid > a.released
    ORDER BY a.invoice_date, a.id
  LOOP
    v_take := least(v_row.owed, v_gross - v_recovered);
    EXIT WHEN v_take <= 0;
    INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
      VALUES (v_tenant, v_row.id, 'recovery_recorded', v_take, p_date, 'commission_payment', v_id, v_me);
    UPDATE public.commission_accruals a SET paid = a.paid - v_take WHERE a.tenant_id = v_tenant AND a.id = v_row.id;
    v_recovered := v_recovered + v_take;
  END LOOP;
  SELECT coalesce(sum(a.paid - a.released), 0) INTO v_owed FROM public.commission_accruals a
    WHERE a.tenant_id = v_tenant AND a.user_id = p_user AND a.paid > a.released;

  v_amount := v_gross - v_recovered;
  v_number := app.next_document_number('CP', p_date);
  IF v_amount > 0 THEN
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, p_date, 'commission_payment', v_id, v_number, left('Commission paid to ' || v_name, 500), NULL, v_me)
      RETURNING journals.id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, 'commission_payable'), v_amount, 0, 'Commission paid to ' || v_name),
             (v_tenant, v_journal, 2, p_account, 0, v_amount, 'Commission ' || v_number);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_me, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', p_date, 'source', 'commission_payment', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', v_amount::text));
  END IF;
  INSERT INTO public.commission_payments (id, tenant_id, number, user_id, payment_date, account_id, gross, recovered, amount, journal_id, note, created_by)
    VALUES (v_id, v_tenant, v_number, p_user, p_date, p_account, v_gross, v_recovered, v_amount, v_journal, nullif(btrim(p_note), ''), v_me);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, v_role, 'commission.pay', 'commission_payment', v_id,
      jsonb_build_object('number', v_number, 'to', v_name, 'person', p_user, 'date', p_date, 'approved', v_gross::text, 'takenBack', v_recovered::text, 'paid', v_amount::text, 'stillOwedBack', v_owed::text));
  RETURN QUERY SELECT v_id, v_number, v_gross, v_recovered, v_amount;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.pay_commission(uuid, date, uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.pay_commission(uuid, date, uuid, text) TO app_runtime;
